#include <stdexcept>

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

static void validate_bst(const TreeNode* root) {
    const TreeNode* prev = nullptr;
    if (!inorder_traversal(root, prev)) {
        throw std::invalid_argument("不满足二分搜索树性质");
    }
}

static bool inorder_traversal(const TreeNode* node, const TreeNode*& prev) {
    if (!node) return true;

    if (!inorder_traversal(node->left, prev)) return false;

    if (prev && prev->val >= node->val) {
        return false;
    }
    prev = node;

    return inorder_traversal(node->right, prev);
}
```

